import React, { useState } from 'react';
import axios from 'axios';

export default function VideoDetection() {
  const [video, setVideo] = useState(null);
  const [videoURL, setVideoURL] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleUpload = async () => {
    if (!video) return;
    const formData = new FormData();
    formData.append("file", video);
    setLoading(true);
    try {
        const res = await axios.post(`${process.env.REACT_APP_BACKEND_URL}/api/`, formData);
        setVideoURL(`${process.env.REACT_APP_BACKEND_URL}${res.data.video}`);
    } catch (err) {
      alert("Upload failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-8 max-w-2xl mx-auto">
      <h2 className="text-2xl font-bold mb-4">🎥 Video Weapon Detection</h2>
      <input type="file" accept="video/*" onChange={e => setVideo(e.target.files[0])} />
      <button onClick={handleUpload} className="mt-4 px-6 py-2 bg-green-600 text-white rounded hover:bg-green-700">
        {loading ? "Processing..." : "Upload & Detect"}
      </button>

      {videoURL && (
        <div className="mt-8">
          <video src={videoURL} controls className="w-full rounded shadow-lg"></video>
        </div>
      )}
    </div>
  );
}
